def build_questions(year, area_data):
    all_q = []
    counters = {"linguagens":0,"humanas":0,"natureza":0,"matematica":0}
    prefix_map = {"linguagens":"L","humanas":"H","natureza":"N","matematica":"M"}
    
    area_order = ["linguagens","humanas","natureza","matematica"]
    
    for area in area_order:
        disc_data = area_data.get(area, {})
        for disc, qs in disc_data.items():
            for ctx, text, pergunta, opts, gab, dif, taxa in qs:
                counters[area] += 1
                seq = counters[area]
                qid = f"{prefix_map[area]}{year}_{seq:02d}"
                all_q.append({
                    "id": qid,
                    "ano": year,
                    "area": area,
                    "disciplina": disc,
                    "contexto": ctx,
                    "texto": text,
                    "pergunta": pergunta,
                    "opcoes": opts,
                    "gabarito": gab,
                    "dificuldade": dif,
                    "taxaAcerto": taxa
                })
    return all_q

# Build 2009
